(* [comment removed for export] *)
Lemma rl_A3b : forall regs m (DW k : Z),
  (1 <= DW < 2 ^ 31)%Z -> k = (DW mod 32)%Z -> (0 <= k < 32)%Z ->
  (forall j, (1 <= j <= 31)%Z -> exists (bs : list byte) (v : word), rdn SEGS m (Z_to_bv 64 (0x1f424 + 4 * j)) 4 = Some bs /\ bytes_le_to_Z bs = bv_unsigned v) ->
  getr regs 6 = Z_to_bv 64 DW ->
  exists regs',
    msteps SEGS (mkst regs (0x7a1bc : word) m rom) (mkst regs' (0x7a2c4 : word) m rom)
    /\ getr regs' 15 = Z_to_bv 64 k
